import childProcess from "node:child_process";
import { appendFileSync } from "node:fs";
import { syncBuiltinESMExports } from "node:module";

const log = "/workspace/scratch/6b51c86fe5f1/validation/docs-child-observations.jsonl";
const original = childProcess.spawnSync;

childProcess.spawnSync = new Proxy(original, {
  apply(target, receiver: unknown, args: unknown[]): unknown {
    const started = Date.now();
    const result: unknown = Reflect.apply(target, receiver, args);
    if (result !== null && typeof result === "object") {
      const error = "error" in result ? result.error : undefined;
      appendFileSync(log, JSON.stringify({
        observerPid: process.pid,
        command: args[0],
        args: args[1],
        durationMs: Date.now() - started,
        pid: "pid" in result ? result.pid : undefined,
        status: "status" in result ? result.status : undefined,
        signal: "signal" in result ? result.signal : undefined,
        error: error instanceof Error ? error.message : undefined,
        errorCode: error !== null && typeof error === "object" && "code" in error
          ? error.code : undefined,
      }) + "\n");
    }
    return result;
  },
});
syncBuiltinESMExports();
